issue_context.body:
Once a provider has been loaded it does not seem possible to unload it again. Fetch calls still return algorithms from the unloaded provider - even though it is reported as unavailable from a call to `OSSL_PROVIDER_available`. See the following test code:

````
#include <stdio.h>
#include <openssl/evp.h>
#include <openssl/provider.h>

int main(void)
{
    OSSL_PROVIDER *legacy = OSSL_PROVIDER_load(NULL, "legacy");
    int ret = 1;
    EVP_MD *md4 = NULL;

    if (legacy == NULL) {
        printf("Failed to load legacy provider\n");
        goto end;
    }

    if (!OSSL_PROVIDER_available(NULL, "legacy")) {
        printf("Legacy provider should be available\n");
        goto end;
    }

    md4 = EVP_MD_fetch(NULL, "MD4", NULL);
    if (md4 == NULL) {
        printf("Failed in first fetch of md4\n");
        goto end;
    }
    EVP_MD_free(md4);


    OSSL_PROVIDER_unload(legacy);
    if (OSSL_PROVIDER_available(NULL, "legacy")) {
        printf("Legacy provider should NOT be available\n");
        goto end;
    }

    md4 = EVP_MD_fetch(NULL, "MD4", NULL);
    if (md4 != NULL) {
        const char *provname = OSSL_PROVIDER_name(EVP_MD_provider(md4));
        printf("EVP_MD_fetch returned unexpected success\n");

        if (OSSL_PROVIDER_available(NULL, provname))
            printf("%s provider is available\n", provname);
        else
            printf("%s provider is not available\n", provname);

        EVP_MD_free(md4);
        goto end;
    }

    ret = 0;
    printf("Success\n");
 end:
    return ret;
}
````

Running this test code produces this output:

````
EVP_MD_fetch returned unexpected success
legacy provider is not available
````
